-- Limpar todas as tabelas para evitar conflitos de chaves duplicadas
TRUNCATE TABLE public.notificacao, public.historico, public.resultado_analitico, public.amostra, public.descarga, public.cliente_parametro, public.autorizacao, public.cliente, public.utilizador, public.parametro, public.etar, public.perfil RESTART IDENTITY CASCADE;

