-- Sincronizar as sequências dos IDs auto-incrementais
SELECT setval('public.perfil_id_perfil_seq', COALESCE((SELECT MAX(id_perfil) FROM public.perfil), 1));
SELECT setval('public.etar_id_etar_seq', COALESCE((SELECT MAX(id_etar) FROM public.etar), 1));
SELECT setval('public.parametro_id_parametro_seq', COALESCE((SELECT MAX(id_parametro) FROM public.parametro), 1));
SELECT setval('public.utilizador_id_utilizador_seq', COALESCE((SELECT MAX(id_utilizador) FROM public.utilizador), 1));
SELECT setval('public.cliente_id_cliente_seq', COALESCE((SELECT MAX(id_cliente) FROM public.cliente), 1));
SELECT setval('public.autorizacao_id_autorizacao_seq', COALESCE((SELECT MAX(id_autorizacao) FROM public.autorizacao), 1));
SELECT setval('public.descarga_id_descarga_seq', COALESCE((SELECT MAX(id_descarga) FROM public.descarga), 1));
SELECT setval('public.amostra_id_amostra_seq', COALESCE((SELECT MAX(id_amostra) FROM public.amostra), 1));
SELECT setval('public.resultado_analitico_id_resultado_seq', COALESCE((SELECT MAX(id_resultado) FROM public.resultado_analitico), 1));
